
using System.Collections;
using UnityEngine;
using UnityEngine.UI;

namespace RioLimpio
{
    // Generated by AI - Arcade Inspection Machine Mechanic (Fulfills Stage 4 Requirement)
    // Manages the dual game modes, countdown timer, visual alerts,
    // time warning sound, animations, and timeout penalties.
    public class WasteInspectionMachine : MonoBehaviour
    {
        [Header("Game Mode Settings (UDL / DUA)")]
        [Tooltip("When enabled, activates arcade time-attack mode with speed pressure. When disabled, plays in relaxed educational mode without time limit.")]
        public bool isTimeAttackMode = false;

        [Header("Arcade Timing Settings")]
        public float timeLimitPerItem = 6.0f;
        public float warningThreshold = 2.5f;
        public float pulseFrequency = 9.0f;

        private float activeCycleDuration = 6.0f;

        [Header("UI Visual Feedback")]
        public RectTransform timerFillRect;
        public Image timerFillImage;
        public float maxBarWidth = 164f;
        public Color normalColor = new Color(0.2f, 0.85f, 0.35f, 1f);
        public Color warningColor = new Color(0.95f, 0.2f, 0.15f, 1f);

        [Header("References")]
        public WasteItemInteractable targetItem;

        private float currentRemainingTime;
        private bool isTimerRunning = false;
        private bool hasPlayedTimeWarning = false;

        private RectTransform itemRect;
        private Image itemIconImage;
        private Outline selectionOutline;
        private Vector3 defaultScale = Vector3.one;
        private Coroutine popInCoroutine;

        private void Awake()
        {
            if (targetItem == null)
            {
                targetItem = GetComponent<WasteItemInteractable>();
            }

            if (targetItem != null)
            {
                itemRect = targetItem.GetComponent<RectTransform>();
                itemIconImage = targetItem.itemIconImage;
                selectionOutline = targetItem.selectionOutline;
            }

            if (timerFillImage != null && timerFillRect == null)
            {
                timerFillRect = timerFillImage.GetComponent<RectTransform>();
            }

            UpdateTimerVisibility();
        }

        // Configures educational vs time-attack mode dynamically.
        public void SetTimeAttackMode(bool activeState)
        {
            isTimeAttackMode = activeState;
            UpdateTimerVisibility();

            if (!isTimeAttackMode)
            {
                isTimerRunning = false;
                hasPlayedTimeWarning = false;
                ResetVisualUrgency();
            }
        }

        private void UpdateTimerVisibility()
        {
            if (timerFillRect != null && timerFillRect.parent != null)
            {
                timerFillRect.parent.gameObject.SetActive(isTimeAttackMode);
            }
            else if (timerFillImage != null)
            {
                timerFillImage.gameObject.SetActive(isTimeAttackMode);
            }
        }

        // Starts or resets the countdown for a newly spawned waste item.
        public void StartInspectionCycle(float? overrideDuration = null)
        {
            activeCycleDuration = overrideDuration.HasValue && overrideDuration.Value > 0f
                ? overrideDuration.Value
                : timeLimitPerItem;

            currentRemainingTime = activeCycleDuration;
            isTimerRunning = isTimeAttackMode;

            // Reset the warning flag for every new waste item.
            hasPlayedTimeWarning = false;

            UpdateTimerVisibility();
            ResetVisualUrgency();

            if (isTimeAttackMode)
            {
                UpdateTimerVisuals(1f);
            }

            if (popInCoroutine != null)
            {
                StopCoroutine(popInCoroutine);
            }

            popInCoroutine = StartCoroutine(AnimatePopInRoutine());
        }

        private IEnumerator AnimatePopInRoutine()
        {
            if (itemRect == null) yield break;

            float duration = 0.22f;
            float elapsed = 0f;

            while (elapsed < duration)
            {
                elapsed += Time.deltaTime;
                float t = Mathf.Clamp01(elapsed / duration);

                // Elastic overshoot curve.
                float s = Mathf.Sin(t * Mathf.PI * 0.5f) * 1.08f;
                itemRect.localScale = new Vector3(s, s, 1f);

                yield return null;
            }

            itemRect.localScale = defaultScale;
        }

        public float GetRemainingTime()
        {
            return currentRemainingTime;
        }

        public float GetTimeRatio()
        {
            if (!isTimeAttackMode) return 1f;

            return activeCycleDuration > 0f
                ? Mathf.Clamp01(currentRemainingTime / activeCycleDuration)
                : 0f;
        }

        // Stops countdown upon classification.
        public void StopTimer()
        {
            isTimerRunning = false;
            ResetVisualUrgency();

            if (isTimeAttackMode)
            {
                UpdateTimerVisuals(1f);
            }
        }

        private void Update()
        {
            if (!isTimeAttackMode || !isTimerRunning || targetItem == null) return;

            if (GameManager.Instance != null && !GameManager.Instance.isGameActive)
                return;

            // Timer runs continuously.
            currentRemainingTime -= Time.deltaTime;

            float ratio = activeCycleDuration > 0f
                ? Mathf.Clamp01(currentRemainingTime / activeCycleDuration)
                : 0f;

            UpdateTimerVisuals(ratio);

            // Play the time warning once when 25% or less remains.
            if (ratio <= 0.25f && !hasPlayedTimeWarning)
            {
                if (AudioManager.Instance != null)
                {
                    AudioManager.Instance.PlayTimeWarningSound();
                }

                hasPlayedTimeWarning = true;
            }

            // Critical time alert: pulsating scale and bright red flashes.
            if (currentRemainingTime <= warningThreshold && currentRemainingTime > 0f)
            {
                float pingPong = Mathf.PingPong(Time.time * pulseFrequency, 1f);

                if (itemRect != null && !targetItem.isBeingDragged)
                {
                    float scaleOffset = Mathf.Sin(Time.time * pulseFrequency * 1.5f) * 0.08f;
                    itemRect.localScale = defaultScale + Vector3.one * scaleOffset;
                }

                if (itemIconImage != null)
                {
                    itemIconImage.color = Color.Lerp(
                        Color.white,
                        new Color(1f, 0.2f, 0.2f, 1f),
                        pingPong
                    );
                }

                if (selectionOutline != null)
                {
                    selectionOutline.enabled = true;
                    selectionOutline.effectColor = new Color(1f, 0.05f, 0.05f, pingPong);
                }
            }
            else
            {
                ResetVisualUrgency();
            }

            // Timeout occurred.
            if (currentRemainingTime <= 0f)
            {
                isTimerRunning = false;
                ResetVisualUrgency();

                if (targetItem.isBeingDragged)
                {
                    targetItem.ResetToHomePosition();
                }

                if (GameManager.Instance != null)
                {
                    GameManager.Instance.OnInspectionTimeout();
                }
            }
        }

        private void ResetVisualUrgency()
        {
            if (itemRect != null && (targetItem == null || !targetItem.isBeingDragged))
            {
                itemRect.localScale = defaultScale;
            }

            if (itemIconImage != null)
            {
                itemIconImage.color = Color.white;
            }

            if (selectionOutline != null && (targetItem == null || !targetItem.isSelectedForClickMode))
            {
                selectionOutline.enabled = false;
            }
        }

        private void UpdateTimerVisuals(float ratio)
        {
            if (timerFillRect != null)
            {
                timerFillRect.sizeDelta = new Vector2(
                    maxBarWidth * ratio,
                    timerFillRect.sizeDelta.y
                );
            }

            if (timerFillImage != null)
            {
                timerFillImage.color = Color.Lerp(warningColor, normalColor, ratio);
            }
        }
    }
}
